    BOARD_BootClockFRO12M_InitClockModule(kClockModule_TRACEClk);
    BOARD_BootClockFRO12M_InitClockModule(kClockModule_USB1Clk);
    BOARD_BootClockFRO12M_InitClockModule(kClockModule_FLEXSPI0Clk);
